    # Recolor the sole compact foreground object to the color of the extended
    # line motif. Demos show 2->5 (demo 3), 0->1 (demo 4), 4->1 (demo 5).
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    comps=[]; seen=set()
    for r in range(h):
